<template><main class="container page-section"><p class="eyebrow">Library</p><h1 class="page-title">收藏</h1><div v-if="!items.length" class="empty">还没有收藏公开文章。</div><div v-else class="list"><RouterLink v-for="post in items" :key="post.id" class="card post" :to="`/posts/${post.slug}`"><small>{{post.username}} · {{date(post.published_at)}}</small><h2>{{post.title}}</h2><p>{{post.excerpt}}</p></RouterLink></div></main></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{RouterLink}from'vue-router';import http from'@/services/http';const items=ref<any[]>([]),date=(v:string)=>new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(v));onMounted(async()=>{try{items.value=(await http.get('/api/bookmarks')).data.items}catch{}})</script>
<style scoped>.list{display:grid;gap:10px}.post{padding:18px;text-decoration:none}.post:hover{border-color:var(--accent)}.post h2{font-size:1.15rem;margin:4px 0}.post p,small{color:var(--muted)}</style>
